export function applyScanToRecord(record, scan) {
  if (!record) return record;
  record.security = {
    scannedAt: new Date().toISOString(),
    filesScanned: scan.files.map((f) => f.path),
    findings: scan.result.findings,
    trustScore: scan.result.trustScore,
